curl -sg 'http://localhost:16686/jaeger/ui/api/traces?service=product-catalog&tags={"error":"true"}&lookback=1h&limit=3' 2>&1 | python3 -c "
import sys,json
d=json.load(sys.stdin)
for t in d.get('data',[]):
    for s in t['spans']:
        tags={x['key']:x['value'] for x in s['tags']}
        if tags.get('error')==True or tags.get('otel.status_code')=='ERROR':
            msg=''
            for l in s.get('logs',[]):
                for f in l['fields']:
                    if f['key'] in ('exception.message','message','event'):
                        msg=f['value']
            print(t['traceID'][:16], s['operationName'], tags.get('rpc.grpc.status_code'), tags.get('otel.status_description') or msg)
" 2>&1 | head -15
